def load() -> pd.DataFrame:
    pattern = 'data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*'
    files = glob.glob(pattern)
    dfs = []
    for file in files:
        try:
            df = pd.read_csv(file)
            dfs.append(df)
        except:
            pass
    return pd.concat(dfs, ignore_index=True) if dfs else pd.DataFrame()

