def load() -> pd.DataFrame:
    from bs4 import BeautifulSoup

    with open('data/legal/input/metropolitan_statistics.html', 'r', encoding='utf-8') as f:
        html_content = f.read()

    soup = BeautifulSoup(html_content, 'html.parser')

    # Find all tables and extract the one with metropolitan area data
    tables = soup.find_all('table')

    for table in tables:
        # Look for table with metro area names and population data
        rows = table.find_all('tr')
        if len(rows) > 0:
            # Try to extract data
            data = []
            for row in rows:
                cells = row.find_all(['td', 'th'])
                if cells:
                    row_data = [cell.get_text(strip=True) for cell in cells]
                    data.append(row_data)

            if data and len(data) > 1:
                # Check if this looks like metro area data
                first_row = ' '.join(data[0]).lower()
                if 'metro' in first_row or 'area' in first_row or 'population' in first_row:
                    df = pd.DataFrame(data[1:], columns=data[0] if data[0] else None)
                    if len(df) > 5:  # Likely the right table
                        return df

    # Fallback: return first substantial table
    if tables:
        rows = tables[0].find_all('tr')
        data = []
        for row in rows:
            cells = row.find_all(['td', 'th'])
            if cells:
                row_data = [cell.get_text(strip=True) for cell in cells]
                data.append(row_data)

        if data:
            df = pd.DataFrame(data[1:], columns=data[0] if data[0] else None)
            return df

    return pd.DataFrame()

def load() -> pd.DataFrame:
    import re
    with open('data/legal/input/metropolitan_statistics.html', 'r', encoding='utf-8') as f:
        html_content = f.read()

    # Use pandas to read HTML tables
    tables = pd.read_html(html_content)

    # Look for the table with metropolitan area data
    for i, table in enumerate(tables):
        if table.shape[1] >= 2:
            # Check if this looks like it contains metro area names and population
            cols = table.columns.tolist()
            first_col = str(table.iloc[0, 0]).lower() if len(table) > 0 else ""
            if any(keyword in str(cols[0]).lower() or keyword in first_col for keyword in ['metro', 'area', 'statistical', 'rank']):
                return table.reset_index(drop=True)

    if len(tables) > 0:
        return tables[1].reset_index(drop=True)

    return pd.DataFrame()

def process(parse_html_metro) -> pd.DataFrame:
    df = parse_html_metro.copy()
    df['normalized_name'] = df['Metropolitan statistical area'].str.replace(r'\s*(MSA|Metropolitan Statistical Area)\s*$', '', regex=True, case=False).str.replace(r'[–—-]', '-', regex=True).str.strip()
    return df[['normalized_name', '2024 estimate', '2020 census']].copy()

def process(clean_identity_theft) -> pd.DataFrame:
    df = clean_identity_theft.copy()
    df['normalized_name'] = df['Metropolitan Area'].str.replace(r'\s*(MSA|Metropolitan Statistical Area|Micropolitan Statistical Area)\s*$', '', regex=True, case=False).str.replace(r'[–—-]', '-', regex=True).str.strip()
    return df[['normalized_name', '# of Reports', 'Metropolitan Area']].copy()
